import { Component, AfterViewInit } from '@angular/core';
import { RouterLink, Router, ActivatedRoute } from '@angular/router';
import { initFakeSubmit } from '../../shared/auth-common';

declare const document: any;

@Component({
  selector: 'app-otp',
  standalone: true,
  imports: [RouterLink],
  templateUrl: './otp.component.html',
  styleUrl: './otp.component.css'
})
export class OtpComponent implements AfterViewInit {
  phone = '';
  private resendCooldown = false;

  constructor(private router: Router, private route: ActivatedRoute) {}

  ngAfterViewInit(): void {
    this.phone = this.route.snapshot.queryParamMap.get('phone') || '';
    const phoneEl = document.getElementById('otp-phone-display');
    if (phoneEl) phoneEl.textContent = this.phone;

    initFakeSubmit('otp-form', 'otp-submit', () => this.router.navigate(['/login']));

    const resendBtn = document.getElementById('otp-resend');
    resendBtn?.addEventListener('click', (e: Event) => {
      e.preventDefault();
      if (this.resendCooldown) return;
      this.resendCooldown = true;
      resendBtn.classList.add('auth-form__resend--sent');
      resendBtn.textContent = 'Code sent';
      setTimeout(() => {
        this.resendCooldown = false;
        resendBtn.classList.remove('auth-form__resend--sent');
        resendBtn.textContent = 'Resend code';
      }, 15000);
    });
  }
}
<div class="auth-body">
  <div class="auth">
    <div class="auth__panel auth__panel--full">
      <div class="auth__navbar auth__navbar--split">
        <a class="auth__back" routerLink="/login">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5"/><path d="M12 19l-7-7 7-7"/></svg>
          Back
        </a>
        <a class="auth__navbar-brand" routerLink="/login">eos</a>
      </div>

      <div class="auth__panel-scroll">
        <div class="auth__card">
          <div class="auth__barbell">
            <span class="plate"></span><span class="plate small"></span>
          </div>

          <div class="auth__head">
            <h1>Verify your phone</h1>
            <p>We sent a code via WhatsApp to <strong id="otp-phone-display"></strong></p>
          </div>

          <form id="otp-form" class="auth-form" novalidate>
            <div class="field">
              <label for="otp-code">Verification code</label>
              <div class="field__control">
                <svg class="field__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="10" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
                <input id="otp-code" type="text" inputmode="numeric" maxlength="6" placeholder="000000" autocomplete="one-time-code" required />
              </div>
              <div id="otp-error" class="field__error"></div>
            </div>

            <button id="otp-submit" type="submit" class="auth-form__submit">
              <svg class="spinner" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><circle cx="12" cy="12" r="9" stroke-opacity=".25"/><path d="M21 12a9 9 0 0 0-9-9"/></svg>
              <span class="btn-label">Verify</span>
            </button>
          </form>

          <div class="auth-form__row">
            <span>Didn't get it?</span>
            <a href="#" id="otp-resend">Resend code</a>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
